const raw = String($json.event_json || '').trim();
let event;
try { event = JSON.parse(raw); } catch { throw new Error('invalid_inventory_approved_json'); }
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuid.test(String(event.event_id || ''))) throw new Error('invalid_event_id');
if (event.event_type !== 'inventory.approved') throw new Error('unsupported_event_type');
if (event.schema_version !== 1) throw new Error('unsupported_schema_version');
if (!uuid.test(String(event.owner_id || ''))) throw new Error('invalid_owner_id');
if (!event.aggregate || event.aggregate.type !== 'INVENTORY_ITEM' || !uuid.test(String(event.aggregate.id || ''))) throw new Error('invalid_aggregate');
if (!event.payload || !uuid.test(String(event.payload.inventory_id || '')) || !uuid.test(String(event.payload.catalogue_id || ''))) throw new Error('invalid_payload_identity');
if (event.payload.status !== 'APPROVED' || !Number.isInteger(event.payload.version) || event.payload.version < 1) throw new Error('invalid_payload_state');
if (String(event.aggregate.id) !== String(event.payload.inventory_id)) throw new Error('aggregate_inventory_mismatch');
const expectedKey = `inventory.approved:${event.payload.inventory_id}:v${event.payload.version}`;
if (String(event.idempotency_key || '') !== expectedKey) throw new Error('invalid_idempotency_key');
return [{json:{event}}];

const crypto = require('crypto');
const event = $json.event;
const secret = String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET || '').trim();
const receiptUrl = String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL || '').trim();
if (secret.length < 32) throw new Error('automation_command_secret_not_configured');
if (!/\/receipt$/.test(receiptUrl)) throw new Error('automation_control_receipt_url_invalid');
const body = JSON.stringify(event);
const timestamp = String(Math.floor(Date.now()/1000));
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body, 'utf8').digest('hex');
return [{json:{command_url:receiptUrl.replace(/\/receipt$/, '/shopify/inventory-approved'),command_body:body,command_timestamp:timestamp,command_signature:signature}}];

const response = $input.first().json || {};
const statusCode = Number(response.statusCode || 0);
if (statusCode < 200 || statusCode >= 300) throw new Error('shopify_publication_http_' + statusCode);
const body = response.body || {};
if (!['PUBLISHED','ALREADY_LINKED'].includes(String(body.status || ''))) throw new Error('shopify_publication_not_verified');
return [{json:{published:true,status:body.status}}];
